output_text:
[
  {
    "id": "pickup_cart_at_entrance",
    "text": "Before shopping, the agent is obliged to take the cart from the entrance cart station rather than merely checking in there.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_station": "at(1,5)",
        "cart_available_at_entrance": "cartAt(1,5)"
      },
      "events": {
        "pickup_entrance_cart": {
          "pre": {
            "and": [
              "entrance_cart_station",
              "cart_available_at_entrance",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "pickup_entrance_cart"
    }
  },
  {
    "id": "return_cart_to_bay",
    "text": "After taking a cart, the agent is obliged to return it to the cart-return bay at (0,1) before the trajectory ends.",
    "abstraction": {
      "state_properties": {
        "return_bay": "at(0,1)",
        "cart_parked_in_return_bay": "cartAt(0,1)"
      },
      "events": {
        "cart_taken": {
          "pre": "PICKUP_CART",
          "post": "hasCart"
        },
        "return_cart_to_bay": {
          "pre": {
            "and": [
              "return_bay",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_in_return_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cart_taken",
      "discharge": "return_cart_to_bay"
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "The agent is forbidden to leave the store while still holding or pushing a cart.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          "pushing_cart"
        ]
      }
    }
  },
  {
    "id": "only_leave_cart_at_return_bay",
    "text": "The agent is forbidden to put down a cart anywhere except the designated cart-return bay at (0,1).",
    "abstraction": {
      "state_properties": {
        "return_bay": "at(0,1)",
        "outside_return_bay": {
          "not": "return_bay"
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "LEAVE_CART",
          "outside_return_bay"
        ]
      }
    }
  },
  {
    "id": "cart_required_for_item_pickup",
    "text": "The agent is forbidden to pick up shelf items unless they currently have the shopping cart.",
    "abstraction": {
      "state_properties": {
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "item_pickup": {
          "pre": "PICKUP_ITEM",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "item_pickup",
          "without_cart"
        ]
      }
    }
  },
  {
    "id": "no_hand_carrying_merchandise",
    "text": "The agent is forbidden to carry merchandise by hand instead of using the cart.",
    "abstraction": {
      "state_properties": {
        "carrying_by_hand": "handFull"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_by_hand"
    }
  },
  {
    "id": "no_noncart_interaction_after_return",
    "text": "Once the cart has been returned, the agent should proceed to the exit without further object interactions.",
    "abstraction": {
      "state_properties": {
        "cart_parked_in_return_bay": "cartAt(0,1)",
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "post_return_interaction": {
          "pre": {
            "and": [
              "cart_parked_in_return_bay",
              "without_cart",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "post_return_interaction"
    }
  },
  {
    "id": "top_corridor_cart_one_way_to_return",
    "text": "When pushing a cart in the top service corridor, the agent is forbidden to move eastward away from the cart-return bay.",
    "abstraction": {
      "state_properties": {
        "top_service_corridor": {
          "or": [
            "at(0,1)",
            "at(1,1)",
            "at(2,1)",
            "at(3,1)",
            "at(4,1)",
            "at(5,1)",
            "at(6,1)",
            "at(7,1)",
            "at(8,1)",
            "at(9,1)"
          ]
        },
        "pushing_cart_in_top_corridor": {
          "and": [
            "hasCart",
            "top_service_corridor"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "pushing_cart_in_top_corridor",
          "E"
        ]
      }
    }
  }
]
